import functools
from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient
import pytest
import asyncio

app = FastAPI()

async def my_dep(q: str = "default"):
    return q

async def my_partial_dep(q: str = "partial"):
    return q

# Partial of a plain function
partial_dep = functools.partial(my_dep, q="partial_value")

@app.get("/")
async def read_root(dep = Depends(partial_dep)):
    return {"dep": dep}

client = TestClient(app)

def test_partial_dep():
    response = client.get("/")
    assert response.status_code == 200
    assert response.json() == {"dep": "partial_value"}

class CallableClass:
    def __call__(self, q: str = "default"):
        return q

class AsyncCallableClass:
    async def __call__(self, q: str = "default"):
        return q

async_callable_instance = AsyncCallableClass()
partial_async_callable = functools.partial(async_callable_instance, q="partial_async_value")

@app.get("/async-callable")
async def read_async_callable(dep = Depends(partial_async_callable)):
    return {"dep": dep}

def test_partial_async_callable():
    response = client.get("/async-callable")
    assert response.status_code == 200
    assert response.json() == {"dep": "partial_async_value"}

if __name__ == "__main__":
    # This is a simple way to run the tests if not using pytest
    import pytest
    pytest.main([__file__])

